static void array_capsule_destroy(PyObject *cap) {
  gpython_array *a = PyCapsule_GetPointer(cap, ARRAY_CAP);
  if (a) gpython_array_release(a);
  Py_XDECREF((PyObject *)PyCapsule_GetContext(cap));
}
static void basis_capsule_destroy(PyObject *cap) {
  gpython_basis *b = PyCapsule_GetPointer(cap, BASIS_CAP);
  if (b) gpython_basis_release(b);
}
static gpython_array *array_arg(PyObject *cap) {
  return (gpython_array *)PyCapsule_GetPointer(cap, ARRAY_CAP);
}
static gpython_basis *basis_arg(PyObject *cap) {
  return (gpython_basis *)PyCapsule_GetPointer(cap, BASIS_CAP);
}
static PyObject *wrap_array(gpython_array *a) {
  if (!a) { PyErr_SetString(PyExc_MemoryError, "received NULL gpython_array"); return NULL; }
  PyObject *cap = PyCapsule_New(a, ARRAY_CAP, array_capsule_destroy);
  if (!cap) gpython_array_release(a);
  return cap;
}
```

The weak binary-op pattern (lines 386–436) is the template to copy verbatim in shape:

```c
typedef int (*binop_fn)(const gpython_basis *, gpython_array *, const gpython_array *,
    const gpython_array *);

static PyObject *
binop(PyObject *args, binop_fn fn, const char *name)
{
  PyObject *bcap, *ocap, *acap, *bcap2;
  if (!PyArg_ParseTuple(args, "OOOO", &bcap, &ocap, &acap, &bcap2))
    return NULL;
  gpython_basis *b = basis_arg(bcap);
  gpython_array *out = array_arg(ocap), *a1 = array_arg(acap), *a2 = array_arg(bcap2);
  if (!b || !out || !a1 || !a2)
    return NULL;
  if (fn(b, out, a1, a2) != 0) {
    PyErr_Format(PyExc_ValueError, "%s: operand shapes incompatible with "
        "the basis (ncomp must be a multiple of num_basis and match)", name);
    return NULL;
  }
  Py_RETURN_NONE;
}

static PyObject *
py_dg_mul(PyObject *self, PyObject *args)
{
  return binop(args, gpython_dg_mul, "dg_mul");
}
```

