398	/* ---- integration --------------------------------------------------------- */
399	int
400	gpython_array_integrate(int ndim, const double *lower, const double *upper,
401	    const int *cells, const gpython_basis *b, int nfields, int op, double factor,
402	    const gpython_array *a, double *out)
403	{
404	  static const enum gkyl_array_integrate_op ops[] = {
405	    GKYL_ARRAY_INTEGRATE_OP_NONE,
406	    GKYL_ARRAY_INTEGRATE_OP_ABS,
407	    GKYL_ARRAY_INTEGRATE_OP_SQ,
408	  };
409	
410	  struct gkyl_rect_grid grid;
411	  gkyl_rect_grid_init(&grid, ndim, lower, upper, cells);
412	
413	  int ones[GKYL_MAX_DIM];
414	  for (int d = 0; d < ndim; ++d)
415	    ones[d] = 1;
416	  struct gkyl_range range;
417	  gkyl_range_init(&range, ndim, ones, cells);
418	  if ((size_t)range.volume != CARR(a)->size)
419	    return 1;
420	
421	  struct gkyl_array_integrate *up =
422	      gkyl_array_integrate_new(&grid, CBAS(b), nfields, ops[op], false);
423	  gkyl_array_integrate_advance(up, CARR(a), factor, NULL, &range, NULL, out);
424	  gkyl_array_integrate_release(up);
425	  return 0;
426	}
427	
428	/* ---- averaging ------------------------------------------------------------
429	 * Single-field only (like gpython_dg_mul_conf_phase): `a`/`weight`/`out` must
430	 * each carry exactly one basis's worth of coefficients per cell -- the
431	 * kernel gkyl_array_average_choose_kernel dispatches has no field-index
432	 * parameter at all, so a multi-field caller must loop, one field at a time,
433	 * in Python (dg/modal.py). */
434	int
435	gpython_array_average(int ndim, const double *lower, const double *upper,
436	    const int *cells, const gpython_basis *b, const gpython_basis *b_avg,
437	    int ndim_avg, const int *cells_avg, const int *avg_dim,
438	    const gpython_array *weight, const gpython_array *a, gpython_array *out)
439	{
440	  size_t nb = (size_t)CBAS(b)->num_basis, nb_avg = (size_t)CBAS(b_avg)->num_basis;
441	  if (CARR(a)->ncomp != nb || CARR(out)->ncomp != nb_avg ||
442	      (weight && (CARR(weight)->ncomp != nb || CARR(weight)->size != CARR(a)->size)))
443	    return 1;
444	
445	  struct gkyl_rect_grid grid;
446	  gkyl_rect_grid_init(&grid, ndim, lower, upper, cells);
447	
448	  int ones[GKYL_MAX_DIM];
449	  for (int d = 0; d < ndim; ++d)
450	    ones[d] = 1;
451	  struct gkyl_range range;
452	  gkyl_range_init(&range, ndim, ones, cells);
453	  if ((size_t)range.volume != CARR(a)->size)
454	    return 1;
455	
456	  int ones_avg[GKYL_MAX_DIM];
457	  for (int d = 0; d < ndim_avg; ++d)
458	    ones_avg[d] = 1;
459	  struct gkyl_range range_avg;
460	  gkyl_range_init(&range_avg, ndim_avg, ones_avg, cells_avg);
461	  if ((size_t)range_avg.volume != CARR(out)->size)
462	    return 1;
463	
464	  /* range_avg doubles as local_avg_ext (mirrors gpython_dg_mul_conf_phase's
465	   * range convention: 1-indexed, lower=1, upper=cells -- there is no ghost
466	   * layer anywhere in the gpython boundary, so the "extended" reduced range
467	   * gkyl_array_average_new only reads to size the integrated weight is
468	   * identical to the reduced range itself). */
469	  struct gkyl_array_average *up = gkyl_array_average_new(&grid, CBAS(b),
470	      CBAS(b_avg), &range, &range_avg, &range_avg,
471	      weight ? CARR(weight) : NULL, avg_dim, false);
472	  gkyl_array_average_advance(up, CARR(a), ARR(out));
473	  gkyl_array_average_release(up);
474	  return 0;
475	}
476	
477	/* ---- evaluate-and-project ------------------------------------------------- */
478	gpython_array *
479	gpython_eval_at_coord_proj(const gpython_basis *b, int cdim_do, int ndim,
480	    const double *lower, const double *upper, const int *cells,
